  "tool.reason.nanomath_replaced": "NanoPlot {version} imports a nanomath module that is not the modified copy NanoPlot ships, so its mean and median read quality would be computed differently. Reinstall NanoPlot in its own environment as shown below, and do not install nanomath into it.",
