  "nanoplot.def.n50": "Lengths sorted from shortest to longest: the first length at which the running total reaches half of all bases. ARVA and SeqKit sort from longest to shortest, which can give a different value.",
  "nanoplot.def.meanQual": "Each read's quality averages its base error probabilities; NanoPlot then averages these per-read qualities again as error probabilities, without weighting by read length. ARVA's mean read quality is the arithmetic mean of the per-read qualities, a different quantity.",
  "nanoplot.def.medianQual": "Median of the per-read qualities (which nanoget stores as 32-bit numbers).",
  "nanoplot.def.longest": "Length of the longest read, with its mean quality.",
  "nanoplot.postNote": "After computing NanoStats.txt, NanoPlot removed {count, plural, one {# read} other {# reads}} shorter than 20 bases with a mean quality above 30, which it treats as basecaller artefacts; the second column describes the remaining reads. ARVA passes no filtering option to NanoPlot.",
