  "nanoplot.aboveNote": "NanoPlot counts reads whose mean quality is strictly above each value (> Q); ARVA's thresholds count reads at or above it (≥ Q). NanoPlot rounds the shares to 0.1% and the yields to 0.1 Mb.",
  "nanoplot.checkTitle": "Cross-check with ARVA (identical definitions)",
  "nanoplot.colResult": "Result",
  "nanoplot.status.agrees": "agrees",
  "nanoplot.status.explained": "{count, plural, one {# zero-length record: ARVA counts it, nanoget skips it} other {# zero-length records: ARVA counts them, nanoget skips them}}",
  "nanoplot.status.differs": "differs",
  "nanoplot.checkNote": "Only the numbers of reads and of bases are defined identically by ARVA and NanoPlot, so only these are checked.",
  "nanoplot.zeroUnknown": "These ARVA statistics were computed before ARVA reported zero-length records; compute them again to see whether such records explain the difference.",
  "nanoplot.sideTitle": "Similar names, different definitions (not compared)",
  "nanoplot.side.above": "Reads above Q{threshold}",
  "nanoplot.side.n50Why": "ARVA sorts lengths from longest to shortest, NanoPlot from shortest to longest. The values can differ on identical reads, so equal values are not a check.",
  "nanoplot.side.aboveWhy": "ARVA counts reads with mean quality ≥ {threshold}, NanoPlot > {threshold}; a read exactly at Q{threshold} counts only for ARVA, and NanoPlot stores per-read qualities with less precision.",
  "nanoplot.sideNote": "NanoPlot's mean and median read quality are not placed next to ARVA's: they are different quantities (see the definitions above).",
  "nanoplot.subsampleNote": "The statistics use every read nanoget kept. The plots in the report are drawn from random subsets of at most 10,000 reads (2,000 for the density plot) chosen without a fixed seed, so for larger files a rerun can look slightly different; such plots say “downsampled” in their title.",
