  "quast.htmlNote": "QUAST's HTML pages are QUAST's own. ARVA opens them in a sandbox without network access or access to ARVA; they load nothing from the internet (their scripts are part of the files). The tables here are ARVA's reading of QUAST's report.tsv.",
  "quast.metric": "Metric (QUAST's name)",
