  "quast.crosscheckDiffers": "differs",
  "quast.agrees": "Same?",
  "quast.equal": "equal",
  "quast.differs": "differs",
  "quast.def.same": "ARVA's assembly card counts every contig; for this check ARVA leaves out the contigs shorter than {min} bp, as QUAST does, so both describe the same contigs (the '(>= 0 bp)' rows count all of them in both programs).",
  "quast.def.nx": "N50, N90, L50, L90 have the same definition in both programs: sort the contigs by length, longest first; Nx is the length of the contig at which the running total first reaches x % of the total length, and Lx is its rank (QUAST compares in floating point, ARVA in whole numbers).",
  "quast.def.gc": "GC (%): QUAST divides G + C by all bases except N, after turning the IUPAC codes M, K, R, Y, W, S, V, B, H, D into N; ARVA divides G + C by A + C + G + T. On the files QUAST accepts (A, C, G, T, N and those codes) the two give the same value.",
  "quast.def.rounding": "QUAST prints GC and N's per 100 kbp with two decimals; ARVA's value is shown with four and counts as equal when it rounds to QUAST's.",
  "quast.def.ns": "# N's per 100 kbp: QUAST turns the IUPAC codes into N before counting, so ARVA compares its count of N plus the other IUPAC codes; the 'N per 100 kb' on ARVA's assembly card counts N only.",
  "quast.field.contigsAll": "All contigs, whatever their length.",
  "quast.field.totalAll": "Total length of all contigs, whatever their length.",
  "quast.field.contigs": "Contigs of at least {min} bp.",
  "quast.field.largest": "Length of the longest contig.",
  "quast.field.total": "Total length of the contigs of at least {min} bp.",
  "quast.field.gc": "(G + C) ÷ (all bases − N) × 100.",
  "quast.field.n50": "Length of the contig at which the contigs, longest first, reach 50 % of the total length.",
  "quast.field.n90": "The same at 90 %.",
  "quast.field.auN": "Area under the Nx curve: the sum of each contig's length weighted by its share of the total length (Li, 2020). Unlike N50 it changes with every contig.",
  "quast.field.l50": "How many contigs, longest first, reach 50 % of the total length.",
  "quast.field.ns": "N bases (gaps or unknown bases) per 100,000 bp of the contigs.",
  "quast.field.ng50": "As N50, but reaching 50 % of the reference length instead of the assembly's.",
  "quast.field.genomeFraction": "Percentage of the reference's bases covered by at least one aligned contig.",
  "quast.field.duplication": "Aligned bases of the assembly ÷ reference bases they cover; above 1 when contigs overlap or repeat sequence.",
  "quast.field.misassemblies": "Breakpoints whose two sides align more than 1 kbp apart, overlap by more than 1 kbp, or lie on different strands or reference sequences (relocations, inversions, translocations).",
