  "perf.docker.not_container": "ARVA runs directly on this computer, not in Docker.",
  "perf.notes.memory": "Memory limits apply only to tools that have one: SPAdes (-m), SPAdes inside Unicycler, Pilon (Java -Xmx) and samtools sort (per thread). Flye, Racon, minimap2, BWA, QUAST, Bakta, Prokka, fastp, FastQC, SeqKit, NanoPlot, Filtlong and MultiQC have none: give them fewer threads instead.",
  "perf.notes.priority": "Inside Docker Desktop, the CPU priority (nice) only orders work inside its Linux virtual machine, where it keeps ARVA's own interface responsive. For macOS, the real limits are the thread count and the CPUs and memory Docker Desktop gives that machine.",
  "perf.notes.flye": "Flye's output can depend on its thread count; every run records the count it used.",
