  "databases.kind.mlst_schemes.description": "The MLST schemes mlst ships in its own package: each scheme's profiles (ST definitions) and allele sequences, and the BLAST index mlst searches. ARVA reads them where mlst's environment installed them, records their date, scheme list and checksum on every MLST job, and ships no updater.",
