  "mlst.warning.partial_alleles": "{count, plural, one {# locus is} other {# loci are}} only partly matched (n?: at least the minimum coverage of allele n): {loci}. The allele is not determined; the gene may be cut at a contig end or hold an insertion or deletion.",
