  "nanoplot.postNote": "Tras calcular NanoStats.txt, NanoPlot eliminó {count, plural, one {# lectura} other {# lecturas}} de menos de 20 bases con calidad media superior a 30, que considera artefactos del basecalling; la segunda columna describe las lecturas restantes. ARVA no pasa ninguna opción de filtrado a NanoPlot.",
