  "nanoplot.side.n50Why": "ARVA ordena las longitudes de la más larga a la más corta y NanoPlot de la más corta a la más larga. Los valores pueden diferir con las mismas lecturas, así que un valor igual no es una comprobación.",
  "nanoplot.side.aboveWhy": "ARVA cuenta las lecturas con calidad media ≥ {threshold} y NanoPlot > {threshold}; una lectura exactamente en Q{threshold} solo cuenta para ARVA, y NanoPlot guarda las calidades por lectura con menos precisión.",
