  "quast.ambiguityNote": "Cuando el mejor alineamiento de un contig cubre más del 99 % de él, QUAST conserva ese alineamiento (y los que puntúan al menos 0,99 × lo mismo) y descarta los demás. Por eso un contig circular que empieza justo después del origen de la referencia puede perder su trozo final en la fracción del genoma: en el genoma sintético de ARVA, un cromosoma idéntico a la referencia pero rotado 1000 de 300 000 pb dio un 99,683 %.",
  "quast.alignerUsed": "Alineado con {name} {version} ({path}).",
  "quast.warningsTitle": "Avisos de QUAST",
  "quast.emptyLog": "QUAST dejó quast.log vacío (QUAST 5.2.0 lo hace con Python 3.13.15 y versiones 3.13 posteriores; esta ejecución usó Python {python}). Su salida de consola se conserva como quast.console.log.",
  "quast.crosscheckTitle": "Comprobación independiente: estadísticas propias de ARVA de los mismos contigs (los de al menos {min} pb)",
