  "quast.def.same": "La ficha del ensamblaje de ARVA cuenta todos los contigs; para esta comprobación ARVA deja fuera los contigs de menos de {min} pb, como QUAST, para que ambos describan los mismos contigs (las filas '(>= 0 bp)' los cuentan todos en los dos programas).",
  "quast.def.nx": "N50, N90, L50 y L90 tienen la misma definición en ambos programas: se ordenan los contigs de más largo a más corto; Nx es la longitud del contig con el que el total acumulado alcanza por primera vez el x % de la longitud total, y Lx es su posición (QUAST compara en coma flotante, ARVA con números enteros).",
  "quast.def.gc": "GC (%): QUAST divide G + C entre todas las bases salvo N, después de convertir en N los códigos IUPAC M, K, R, Y, W, S, V, B, H, D; ARVA divide G + C entre A + C + G + T. En los archivos que QUAST acepta (A, C, G, T, N y esos códigos) ambos dan el mismo valor.",
  "quast.def.rounding": "QUAST escribe el GC y las N por 100 kpb con dos decimales; el valor de ARVA se muestra con cuatro y cuenta como igual si al redondearlo da el de QUAST.",
