  "tool.reason.prokka_db_missing": "No se encontraron las bases de datos de Prokka donde las guarda el paquete de Debian (/usr/share/prokka/db), así que Prokka no puede anotar. El paquete prokka 1.14.6+dfsg-6 o posterior de Debian/Ubuntu las incluye; los anteriores no traen los conjuntos de proteínas.",
  "annotation.intro": "Anota un ensamblaje: encuentra genes (CDS), tRNA, rRNA y otros ARN, matrices CRISPR y huecos, y asigna a las proteínas las funciones que respaldan sus coincidencias en la base de datos. Se recomienda Bakta; Prokka se ofrece como alternativa. Antes de ejecutar nada se muestra qué puede hacer cada anotador en este equipo.",
