  "perf.docker.steps": "Abre Docker Desktop → Settings → Resources → Advanced, pon estos valores y aplícalos; después vuelve a iniciar ARVA con scripts/start.sh.",
  "perf.docker.moreCpus": "Más CPU de las recomendadas no causan problemas: el número de hilos de ARVA es lo que limita sus herramientas.",
  "perf.docker.partial": "Se desconocen algunos datos del Mac, así que no hay una recomendación completa para Docker Desktop.",
  "perf.docker.host_unknown": "Sin recomendación para Docker Desktop: el equipo es desconocido. En un Mac, inicia ARVA con scripts/start.sh.",
  "perf.docker.not_container": "ARVA se ejecuta directamente en este equipo, no en Docker.",
  "perf.notes.memory": "Los límites de memoria solo se aplican a las herramientas que tienen uno: SPAdes (-m), SPAdes dentro de Unicycler, Pilon (Java -Xmx) y samtools sort (por hilo). Flye, Racon, minimap2, BWA, QUAST, Bakta, Prokka, fastp, FastQC, SeqKit, NanoPlot, Filtlong y MultiQC no tienen ninguno: dales menos hilos en su lugar.",
  "perf.notes.priority": "Dentro de Docker Desktop, la prioridad de CPU (nice) solo ordena el trabajo dentro de su máquina virtual Linux, donde mantiene ágil la propia interfaz de ARVA. Para macOS, los límites reales son el número de hilos y las CPU y la memoria que Docker Desktop da a esa máquina.",
  "perf.notes.flye": "El resultado de Flye puede depender de su número de hilos; cada ejecución registra el número que usó.",
  "perf.notes.applies": "Un cambio se aplica a los trabajos creados después. ARVA_TOOL_THREADS y ARVA_TOOL_MEMORY_GB, cuando están definidos, limitan todos los perfiles.",
