  "nav.desc.import": "Importación de FASTQ/FASTA con validación y checksums.",
  "nav.desc.qc": "Estadísticas de lecturas, FastQC, comprobación cruzada con SeqKit y filtrado con fastp/Filtlong.",
  "nav.desc.assembly": "Ensamblaje con lecturas largas, cortas e híbrido (primero Flye), con evaluación QUAST y estadísticas de contigs.",
  "nav.desc.annotation": "Anotación del genoma con Bakta (Prokka como alternativa), navegador de genes y exportación a FASTA/GFF3/GenBank.",
  "nav.desc.genomic": "MLST, resistoma con AMRFinderPlus, viruloma, búsqueda BLAST e identificación taxonómica.",
  "nav.desc.explorer": "Navegador lineal e interactivo del genoma con pistas de anotación, GC, sesgo GC y cobertura.",
