  "databases.kind.bakta.name": "Base de datos de Bakta",
  "databases.kind.bakta.description": "La base de datos con la que anota Bakta, ligera o completa. Bakta 1.12.2 (la versión que incluye ARVA) necesita el esquema de base de datos 6.",
  "databases.kind.bakta.recognise": "version.json con date, major, minor y type, y los archivos que comprueba Bakta 1.12.2 (FILE_NAMES de bakta/db.py) más psc.dmnd (completa) o pscc.dmnd (ligera).",
  "databases.kind.bakta.version_from": "version.json: major.minor; type indica ligera o completa.",
