  "databases.kind.bakta.licence": "CC BY 4.0 (registro de Zenodo de la base de datos 6.0)",
  "databases.kind.bakta.tool0": "Bakta 1.12.2 solo acepta el esquema 6 (major 6, cualquier minor); la base de datos 6.0 necesita Bakta 1.11 o posterior",
  "databases.kind.amrfinderplus.name": "Base de datos de AMRFinderPlus",
  "databases.kind.amrfinderplus.description": "El Reference Gene Catalog del NCBI y sus HMM de genes de resistencia a antimicrobianos, de respuesta al estrés y de virulencia, y de mutaciones puntuales, que lee AMRFinderPlus (y el sistema experto de AMR de Bakta desde amrfinderplus-db/latest dentro de una base de datos de Bakta).",
  "databases.kind.amrfinderplus.recognise": "version.txt, database_format_version.txt y los archivos de datos que lee amrfinder (AMRProt.fa, AMR.LIB, AMR_CDS.fa, fam.tsv, taxgroup.tsv, AMRProt-mutation.tsv, AMRProt-susceptible.tsv, AMRProt-suppress.tsv); AMRProt.fa.phr muestra que se construyeron los índices de BLAST.",
  "databases.kind.amrfinderplus.version_from": "version.txt (por ejemplo 2026-08-07.1); database_format_version.txt indica la versión mínima de AMRFinderPlus.",
  "databases.kind.amrfinderplus.typical_size": "Unos 140 MB de archivos de la versión (2026-08-07.1 en el FTP del NCBI), más los índices de BLAST y HMM que construye amrfinder_update.",
  "databases.kind.amrfinderplus.download_note": "El NCBI publica cada versión como una carpeta de archivos sueltos sin sumas de comprobación, y amrfinder_update construye después índices con BLAST y HMMER: registra una carpeta preparada por amrfinder_update.",
  "databases.kind.amrfinderplus.licence": "Dominio público (obra del Gobierno de los Estados Unidos; aviso del NCBI en las fuentes de AMRFinderPlus)",
  "databases.kind.amrfinderplus.tool0": "la versión del programa debe ser al menos la de database_format_version.txt; AMRFinderPlus 4.2.7 necesita datos 2025-09-22.2 o posteriores",
  "databases.kind.amrfinderplus.unconfirmed0": "No se midió el tamaño de los índices que añade amrfinder_update.",
  "databases.kind.gtdbtk.name": "Datos de referencia de GTDB-Tk",
  "databases.kind.gtdbtk.description": "El paquete de una versión de la Genome Taxonomy Database con el que GTDB-Tk clasifica genomas.",
  "databases.kind.gtdbtk.recognise": "metadata/metadata.txt con una línea VERSION_DATA y taxonomy/gtdb_taxonomy.tsv; GTDB-Tk 2.8.0 lee además msa/, masks/, pplacer/, skani/, radii/, mrca_red/, markers/ y split/.",
  "databases.kind.gtdbtk.version_from": "VERSION_DATA en metadata/metadata.txt (por ejemplo r232).",
  "databases.kind.gtdbtk.typical_size": "Unos 100 GB descomprimida para R232 (guía de instalación de GTDB-Tk); el archivo comprimido de R232 tiene 60.806.405.195 bytes.",
  "databases.kind.gtdbtk.download_note": "Carpetas por versión con un MD5SUM.txt (versión 232.0).",
  "databases.kind.gtdbtk.licence": "CC BY-SA 4.0 (página de descargas de GTDB)",
  "databases.kind.gtdbtk.tool0": "R232 necesita GTDB-Tk 2.7.0 o posterior; R226 y R220: de 2.4.x a 2.6.1; R214 y R207_v2: de 2.1.0 a 2.3.2 (guía de instalación de GTDB-Tk); GTDB-Tk 2.8.0 solo acepta R232",
  "databases.kind.gtdbtk.unconfirmed0": "No se comprobó la estructura de carpetas de las versiones anteriores a R232; las versiones de GTDB-Tk anteriores a 2.7 leen otras carpetas.",
  "databases.kind.skani.name": "Base de datos de esbozos de skani",
  "databases.kind.skani.description": "Genomas procesados por skani sketch (por ejemplo los representantes de especie de GTDB ya procesados), en los que se busca con skani search la identidad nucleotídica media.",
  "databases.kind.skani.recognise": "markers.bin2 (skani 0.4) o markers.bin (anteriores), con sketches.db2 e index.db2 (o sketches.db e index.db), o un archivo .sketch por genoma.",
  "databases.kind.skani.version_from": "No figura en los archivos: la versión de GTDB la declaras tú (ARVA sugiere una a partir del nombre de la carpeta). README.txt, que escribe skani 0.4, indica la versión de skani que la construyó.",
  "databases.kind.skani.typical_size": "GTDB R232 y R226: unos 30 GB comprimida, 50 GB descomprimida (wiki de skani).",
  "databases.kind.skani.download_note": "Las bases de datos ya procesadas se ofrecen por HTTP sin cifrar y sin sumas de comprobación publicadas.",
  "databases.kind.skani.licence": "skani: MIT o Apache-2.0; las bases de datos de GTDB ya procesadas no indican una licencia propia",
  "databases.kind.skani.tool0": "las bases de datos escritas por skani 0.4 (markers.bin2) necesitan skani 0.4.0 o posterior; skani 0.4 sigue leyendo las bases anteriores (markers.bin)",
  "databases.kind.sylph.name": "Base de datos de sylph",
  "databases.kind.sylph.description": "Un archivo de base de datos de sylph (.syldb, o .syl2db para las bases de dos etapas) con genomas procesados, para perfilar lecturas con sylph profile.",
  "databases.kind.sylph.recognise": "Un archivo terminado en .syldb o .syl2db (los sufijos que lee sylph 1.0.0, src/constants.rs).",
  "databases.kind.sylph.version_from": "No figura de un modo que ARVA lea: la declaras tú (ARVA sugiere la versión y el valor de -c a partir del nombre del archivo, p. ej. gtdb-r232-c200-dbv1.syldb).",
  "databases.kind.sylph.typical_size": "GTDB R232: 24 GB (-c 200), 4,9 GB (-c 1000) o 19 GB (dos etapas) (documentación de sylph).",
  "databases.kind.sylph.download_note": "Se ofrece por HTTP sin cifrar (y una réplica en Google Cloud) sin sumas de comprobación publicadas.",
