  "databases.kind.kraken2.name": "Índice de Kraken 2",
  "databases.kind.kraken2.description": "Una base de datos (índice) de Kraken 2 para la clasificación taxonómica de lecturas, como la colección Standard que construyen los responsables de Kraken 2.",
  "databases.kind.kraken2.recognise": "hash.k2d, opts.k2d y taxo.k2d (los archivos que abre el script kraken2); los índices de los responsables incluyen además inspect.txt, library_report.tsv, ktaxonomy.tsv, names.dmp, nodes.dmp y un archivo .md5 con el MD5 de cada archivo.",
  "databases.kind.kraken2.version_from": "El nombre del archivo comprimido en el .md5 del índice (por ejemplo k2_standard_20260626.tar.gz: Standard, 2026-06-26); si no, la declaras tú.",
